public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int N_pathCount, time, goc;
		while (in.hasNext()) {
			N_pathCount = in.nextInt();
			time = in.nextInt();
			System.out.print(goc = goc(N_pathCount, time));
			System.out.print(" ");
			System.out.println(N_pathCount / goc * time);
		}
	}

	static int goc(int N_pathCount, int time) {
		if (time != 0) return goc(time, N_pathCount % time);
		else return N_pathCount;
	}
}

