public class Main{

	public static void main(String[] args) {

		Scanner start = new Scanner(System.in);
		int max2 = start.nextInt();
		int[] min = new int[max2];
		String out[] = new String[max2];
		String arr = "";

		for(int m=0 ; m<out.length ; m++) {
			min[m] = start.nextInt();
		}
		String isPrime = "";
		for(int d=0 ; d<min.length ; d++) {
			isPrime += min[d];
			if(d+1<min.length)
				isPrime += " ";
		}
		System.out.println(isPrime);
		solve(min);
	}

	public static void solve(int[] min) {
		for(int m=1 ; m<min.length ; m++) {
			int result_list = min[m];
			int movableIndex = m - 1;
			while(movableIndex >= 0 && min[movableIndex] > result_list) {
				min[movableIndex + 1] = min[movableIndex];
				movableIndex--;
			}
			min[movableIndex + 1] = result_list;
			String isPrime = "";
			for(int d=0 ; d<min.length ; d++) {
				isPrime += min[d];
				if(d+1<min.length)
					isPrime += " ";
			}
			System.out.println(isPrime);
		}
	}
}

