public class Main {
	public static void GetLcm(int count,int change_cnt){
		int tmpn=count;
		while(change_cnt!=0){
			tmpn = count % change_cnt; 
			count = change_cnt; 
			change_cnt = tmpn; 
		}
		System.out.println(count);
	}
	public static void main(String[] args) {
		Scanner kyori = new Scanner(System.in);
		int count = kyori.nextInt();
		int change_cnt = kyori.nextInt();
		if(count>change_cnt)
			GetLcm(count,change_cnt);
		else
			GetLcm(change_cnt,count);
	}

}

