import java.util.Scanner;

public class Main {

	public static int isPrime(int[] s2) {
		if (s2.length == 0)
			return 0;
		int dist = Integer.MIN_VALUE;
		int totalDist = s2[0];
		for (int i = 1; i < s2.length; i++) {
			dist = Math.max(s2[i] - totalDist, dist);
			totalDist = Math.min(s2[i], totalDist);
		}
		return dist;
	}

	public static void main(String[] args) {
		Scanner sum = new Scanner(System.in);
		int array = sum.nextInt();
		int[] s2 = new int[array];
		for (int i = 0; i < array; i++) {
			s2[i] = sum.nextInt();
		}
		System.out.println(isPrime(s2));
	}

}

