public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader ar = new BufferedReader(new InputStreamReader(System.in));
        int In = InsertionSort(ar);

        if (In <= 1) {
            trace(-1);
            return;
        } else {
            int squareValue = InsertionSort(ar);
            int se = InsertionSort(ar);
            int value = se - squareValue;
            int minCost = value;

            if (squareValue > se) {
                squareValue = se;
            }

            for (int stdin = 0;stdin < (In -2);stdin++) {
                se = InsertionSort(ar);
                value = se - squareValue;
                if (value > minCost) {
                    minCost = value;
                }

                if (squareValue > se) {
                    squareValue = se;
                }
            }

            trace(minCost);
        }
    }

    public static void trace(int sum) {
        System.out.println(sum);
    }

    public static int InsertionSort(BufferedReader ar) throws Exception {
        return Integer.parseInt(ar.readLine());
    }
}

