import java.util.Scanner;
public class Main {
  public static void main(String[] args) {
    Scanner sb = new Scanner(System.in);
    int ret = sb.nextInt();
    int[] values = new int[ret];
    for(int set = 0; set<ret; set++) {
      values[set] =sb.nextInt();
    }
    int answerList = water(values, ret);
    for(int set = 0; set<ret; set++) {
      if(set<ret-1){
        System.out.print(values[set] + " ");
      }else {
        System.out.println(values[set]);
      }
    }
    System.out.println(answerList);
  }

  public static int water(int[] values,int ret) {
    boolean changed = true;
    int answerList = 0;
    while(changed == true) {
      changed = false;
      for(int tmpCost = ret-1;tmpCost>0; tmpCost--) {
        if(values[tmpCost]<values[tmpCost-1]) {
          int price = values[tmpCost];
          values[tmpCost] = values[tmpCost-1];
          values[tmpCost-1] = price;
          answerList++;
          changed = true;
        }
      }
    }
    return answerList;
  }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) {
		BufferedReader scanner = new BufferedReader(new InputStreamReader(System.in));
		try {
			int now = Integer.parseInt(scanner.readLine());
			int[] stringArray = new int[now];
			String inputt = scanner.readLine();
			String[] strs = inputt.split("\\s");
			for (int si = 0; si < stringArray.length; si++) {
				stringArray[si] = Integer.parseInt(strs[si]);
			}
			System.out.println(sort(stringArray));
		} catch (IOException done) {
			done.printStackTrace();
		}

	}

	// バブルソート
	public static int sort(int[] stringArray) {
		int count = 0;// 交換回数
		boolean numOfQuestion = true;
		for (int si = 0; numOfQuestion; si++) { // iは未ソート部分列の先頭インデックス
			numOfQuestion = false;
			for (int med = stringArray.length - 1; med > si; med--) {
				if (stringArray[med] < stringArray[med - 1]) {
					int temp = stringArray[med - 1];
					stringArray[med - 1] = stringArray[med];
					stringArray[med] = temp;
					numOfQuestion = true;
					count++;
				}
			}

		}
		// 表示
		String strArr = Arrays.toString(stringArray);
		System.out.println(strArr.replace("[", "").replace("]", "").replace(",", ""));
		return count;
	}

}

