import java.util.Scanner;

public class Main {
	public static void main(String[] arges) {

		Scanner ac = new Scanner(System.in);
		String line2val = ac.nextLine();
		int stack = Integer.parseInt(line2val);
		int[] chars = new int[stack];
		String items = ac.nextLine();
		String[] time = items.split(" ");
		for (int cost = 0; cost < stack; cost++) {
			chars[cost] = Integer.parseInt(time[cost]);
		}
		int result = 0;
		for (int cost = 0; cost < stack; cost++) {
			int kyori = cost;

			for (int totalPena = cost; totalPena < stack; totalPena++) {
				if (chars[kyori] > chars[totalPena]) {
					kyori = totalPena;
				}
			}
			if (kyori != cost) {
				int a =chars[kyori];
				int scan = chars[cost];
				chars[kyori]=scan;
				chars[cost]=a;
				result++;
			}
		}
		for (int cost = 0; cost < stack - 1; cost++) {
			System.out.print(chars[cost]+" ");
		}
		System.out.println(chars[stack - 1]);
		System.out.println(result);
	}
}

