		int max2[] = new int[e];

		for(counts = 0; counts < e; counts++){
			max2[counts] = ans.nextInt();
		}

		findJumpCost(e, max2);
	}
	public static void findJumpCost(int e, int max2[]){
		int posision = 0;
		for (int counts = 0; counts <= e - 1; counts++){
			int list = counts;
			for(int acResult = counts; acResult <= e - 1; acResult++){
				if(max2[acResult] < max2[list]){
					list = acResult;
				}
			}
			if(max2[counts] != max2[list]) posision++;
			int con = max2[counts];
			max2[counts] = max2[list];
			max2[list] = con;
		}
		for(int counts = 0; counts < e; counts++){
			if(counts == e - 1) System.out.println(max2[counts]);
			else System.out.print(max2[counts] + " ");
		}
		System.out.println(posision);
	}
}

