import java.util.Scanner;

public class Main {

	static int isPrime(int[] arr1, int[] b) {
		int range = 0;
		int second = 0;
		for(int minj=0; minj<b.length; minj++){
			int time = 0;
			int param = arr1.length-1;

			while(time<=param)
			{
				second = (time+param)/2;
//				System.out.println("mid: "+ mid);
				if(b[minj]==arr1[second])
				{
					range++;
					break;
				}
				else if(b[minj]<arr1[second])
				{
					param = second-1;
				}
				else if(b[minj]>arr1[second])
				{
					time = second+1;
				}
			}		
		}
		return range;
	}

    public static void main(String argv[]) {

        Scanner in = new Scanner(System.in);
        int num1 = in.nextInt();

        int arr[];    //declaring array
        arr = new int[num1];  // allocating memory to array

     // accessing the numbers in the second line
        for (int minj = 0; minj < arr.length; minj++){
        	arr[minj] = in.nextInt();
        }

        int num2 = in.nextInt();
        int stoneCount[];    //declaring array
        stoneCount = new int[num2];  // allocating memory to array

     // accessing the numbers in the second line
        for (int minj = 0; minj < stoneCount.length; minj++){
        	stoneCount[minj] = in.nextInt();
        }

        int minimumIncurred = isPrime(arr, stoneCount);

        System.out.println(minimumIncurred);
        in.close();
    }
}

import java.util.HashSet;
import java.util.Scanner;
