public class Main {

	public static void main(String[] args) {
		Scanner cost = new Scanner(System.in);

		int result = cost.nextInt();
		int[] seisuu = new int[result];
		for (int index = 0; index < result; index++) {
			seisuu[index] = cost.nextInt();
		}

		int nameAndTime = cost.nextInt();
		int[] isPrime = new int[nameAndTime];
		for (int index = 0; index < nameAndTime; index++) {
			isPrime[index] = cost.nextInt();
		}

		Set<Integer> swapCount = new HashSet<Integer>();


		for (int index = 0; index < nameAndTime; index++) {
			int changedCntFrm1 = 0;
			int string = result - 1;

			while(changedCntFrm1 <= string) {
				int center = (changedCntFrm1 + string) / 2;
				if(seisuu[center] == isPrime[index]){
					swapCount.add(index);
					break;
				} else if (seisuu[center] < isPrime[index]) {
					changedCntFrm1 = center + 1;
				} else {
					string = center - 1;
				}
			}
		}

		Integer[] tile = swapCount.toArray(new Integer[0]);
		System.out.println(tile.length);

		cost.close();
	}

}

import java.util.*;

public class Main {

	public static int selectionSort(int[] order, int[] line) {
		int second=0;
		for (int minsum = 0; minsum < line.length; minsum++) {
			if (isPrime(order, line[minsum])) {
				second++;
			}
		}
		return second;
	}

	public static boolean isPrime( int[] order,  int current) {
		int len = 0;
		int param = order.length - 1;

		while ( len <= param) {
			int min = (param+len)/2;
			if(order[min] < current) {
				len = min + 1;
			}
			else if(order[min] > current) {
				param = min - 1;
			}
			else {
				return true;
			}
		}
		return false;

	}

	public static void main(String[] args) {
		Scanner result = new Scanner(System.in);

		int sizearray = result.nextInt();

		int order[] = new int[sizearray];

		for (int minsum = 0; minsum < sizearray; minsum++) {
			order[minsum] = result.nextInt();

		}

		int smaller = result.nextInt();
		int line[] = new int[smaller];
		for (int minsum = 0; minsum < smaller; minsum++) {
			line[minsum] = result.nextInt();

		}
		System.out.println(selectionSort(order, line));

		result.close();
	}

}

