class FastScanner {

    private final InputStream in = System.in;
    private final byte[] bufferPointer = new byte[1024];
    private int ptr = 0;
    private int buf = 0;

    private boolean hasNextByte() {
        if (ptr < buf) {
            return true;
        } else {
            ptr = 0;
            try {
                buf = in.read(bufferPointer);
            } catch (IOException scanner) {
                scanner.printStackTrace();
            }
            if (buf <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readChar() {
        if (hasNextByte()) {
            return bufferPointer[ptr++];
        } else {
            return -1;
        }
    }

    private static boolean skipUnprintable(int ca) {
        return 33 <= ca && ca <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !skipUnprintable(bufferPointer[ptr])) {
            ptr++;
        }
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder s = new StringBuilder();
        int ans = readChar();
        while (skipUnprintable(ans)) {
            s.appendCodePoint(ans);
            ans = readChar();
        }
        return s.toString();
    }

    public long nextLine() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean min = false;
        int ans = readChar();
        if (ans == '-') {
            min = true;
            ans = readChar();
        }
        if (ans < '0' || '9' < ans) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= ans && ans <= '9') {
                n *= 10;
                n += ans - '0';
            } else if (ans == -1 || !skipUnprintable(ans)) {
                return min ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            ans = readChar();
        }
    }

    public int nextInt() {
        long nl = nextLine();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDoubleArray() {
        return Double.parseDouble(next());
    }

    public int[] isEndOfLine(int menu) {
        int[] arr = new int[menu];
        for (int mi = 0; mi < menu; mi++) {
            arr[mi] = nextInt();
        }
        return arr;
    }

    public long[] longreadArray(int menu) {
        long[] arr = new long[menu];
        for (int mi = 0; mi < menu; mi++) {
            arr[mi] = nextLine();
        }
        return arr;
    }

    public double[] arrayDouble(int menu) {
        double[] arr = new double[menu];
        for (int mi = 0; mi < menu; mi++) {
            arr[mi] = nextDoubleArray();
        }
        return arr;
    }

    public String[] shuffle(int menu) {
        String[] arr = new String[menu];
        for (int mi = 0; mi < menu; mi++) {
            arr[mi] = next();
        }
        return arr;
    }

}

