	public static int[] Struct(int[] number){
		int[] boxstr = number;
		int ary = 0;
		for(int minR = 0 ; minR < number.length; minR++){
			for(int min = minR+1 ; min < number.length;min++){
				if(boxstr[minR] > boxstr[min]){
					ary = boxstr[minR];
					boxstr[minR] = boxstr[min];
					boxstr[min] = ary;
				}
			}
		}
		return boxstr;
	}

}

