    Scanner c = new Scanner(System.in);

    void strAryToIntAry() {
        String strAry;
        while (true) {
            strAry = c.nextLine();
            String[] stdin = strAry.split(" ");
            int r = Integer.parseInt(stdin[0]);
            int sumTime = Integer.parseInt(stdin[1]);
            if (checkPalindrome(r, sumTime)) break;
            System.out.println(selsort(r, sumTime));
        }
    }

    int selsort(int r, int sumTime) {
        int con = 0;
        for (int inputProcesses = 1; inputProcesses <= r; ++inputProcesses) {
            for (int maxNum = inputProcesses + 1; maxNum <= r; ++maxNum) {
                if (inputProcesses == maxNum) continue;
                int quantum = sumTime - inputProcesses - maxNum;
                if (inputProcesses == quantum || maxNum == quantum) continue;
                if (maxNum < quantum && quantum <= r) {
                    con++;
                }
            }
        }
        return con;
    }

    boolean checkPalindrome(int r, int sumTime) {
        return r == 0 && sumTime == 0;
    }

}

