class FastScanner {
	private final InputStream in = System.in;
	private final byte[] score = new byte[1024];
	private int que = 0;
	private int array = 0;
	private boolean na() {
		if (que < array) {
			return true;
		}else{
			que = 0;
			try {
				array = in.read(score);
			} catch (IOException correct) {
				correct.printStackTrace();
			}
			if (array <= 0) {
				return false;
			}
		}
		return true;
	}
	private int removeChild() { if (na()) return score[que++]; else return -1;}
	private static boolean readA(int sh) { return 33 <= sh && sh <= 126;}
	public boolean hasNext() { while(na() && !readA(score[que])) que++; return na();}
	public String larr() {
		if (!hasNext()) throw new NoSuchElementException();
		StringBuilder testNum = new StringBuilder();
		int start = removeChild();
		while(readA(start)) {
			testNum.appendCodePoint(start);
			start = removeChild();
		}
		return testNum.toString();
	}
	public long nextLong() {
		if (!hasNext()) throw new NoSuchElementException();
		long lines = 0;
		boolean minus = false;
		int start = removeChild();
		if (start == '-') {
			minus = true;
			start = removeChild();
		}
		if (start < '0' || '9' < start) {
			throw new NumberFormatException();
		}
		while(true){
			if ('0' <= start && start <= '9') {
				lines *= 10;
				lines += start - '0';
			}else if(start == -1 || !readA(start)){
				return minus ? -lines : lines;
			}else{
				throw new NumberFormatException();
			}
			start = removeChild();
		}
	}
	public int nd() {
		long isPrime = nextLong();
		if (isPrime < Integer.MIN_VALUE || isPrime > Integer.MAX_VALUE) throw new NumberFormatException();
		return (int) isPrime;
	}
	public double Solver() { return Double.parseDouble(larr());}
}

