    static int isPrime(String col, String a2) {
        int reader = col.length();
        int minus = a2.length();

        int ms = Integer.MAX_VALUE;
        for (int li = 0; li < minus - reader + 1; li++) {
            int ar = 0;
            for (int ch = 0; ch < reader; ch++) {
                if (col.charAt(ch) != a2.charAt(li + ch)) {
                    ar++;
                }
            }

            ms = Math.min(ar, ms);
        }

        return ms;
    }

