     * ロジック
     */
    public static int isPrime(String flag) {
        if (flag.matches("R{3}")){
            return 3;
        } else if (flag.matches(".*R{2}.*")) {
            return 2;
        } else if (flag.matches(".*R.*")) {
            return 1;
        } else {
            return 0;
        }
    }
}

