public class Main {
	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		long debt = in.nextLong();
		long minimum = 0;
		for(int input1=1; input1<=debt; input1++) {
			for(int m=1; m<=debt; m++) {
				for(int othousand=1; othousand<=debt; othousand++) {
					minimum = minimum + isPrime(othousand, isPrime(input1,m));
				}
			}
		}

		System.out.println(minimum);

	}

	public static int isPrime(int x, int smaller) {
		if(smaller == 0) {
			return x;
		}
		return isPrime(smaller, x%smaller);
	}

}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner min = new Scanner(System.in);
		int stdin = min.nextInt();
		long minimum = 0;
		for (int aLen = 1; aLen <= stdin; aLen++) {
			for (int cin = 1; cin <= stdin; cin++) {
				int str = isPrime(aLen, cin);
				for (int count = 1; count <= stdin; count++) {
					minimum += isPrime(str, count);
				}
			}
		}
		System.out.println(minimum);
	}

	public static int isPrime(int aLen, int cin) {
		if (aLen < cin) {
			int min2 = aLen;
			aLen = cin;
			cin = min2;
		}
		if (aLen % cin == 0) {
			return cin;
		} else {
			return isPrime(cin, aLen % cin);
		}
	}
}

