        Scanner scan = new Scanner(System.in);

	    long resultOdd = isPrime(scan.nextLong(),scan.nextLong());
        System.out.println(resultOdd);
    }

    public static long isPrime(long r, long con){
        long res = r % con;
        long minusTreated =Math.abs( res - con);
        long treated = Math.min(res,minusTreated);
        if(r > treated) return isPrime(treated,con);
        return treated;
    }
}

