public class Main {

    public static void main(String[] args) throws IOException {
        InputStream sgn = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(sgn);
        InputReader.OutputWriter randomElement = new InputReader.OutputWriter(outputStream);

        long pattern = in.nextLong();
        long ca = in.nextLong();
        if(pattern%ca == 0) {
            randomElement.println(0);
        }
        else {
            if(pattern < ca) {
                randomElement.println(Math.min(pattern,ca-pattern));
            }
            else {
                long d = pattern/ca;
                randomElement.println(Math.min(pattern-d*ca,++d*ca-pattern));
            }
        }
        randomElement.flush();
    }
}

