import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner m = new Scanner(System.in);

		int primeNum = m.nextInt();
		int digit = m.nextInt();

		m.close();

		List<Integer> numberList = new ArrayList<Integer>();

		int result_list = 2;
		for (int stdin = 1; stdin <= primeNum; stdin++) {
			numberList.add(result_list);
			result_list += 2;
		}

		int answer = 1;
		for (int stdin = 1; stdin <= digit; stdin++) {
			numberList.add(answer);
			answer += 2;
		}

		int isPrime = 0;
		for (int stdin = 0; stdin < numberList.size(); stdin++) {
			for (int taro = stdin; taro < numberList.size(); taro++) {
				int parent = numberList.get(stdin).intValue();
				int count = numberList.get(taro).intValue();

				if (parent == count) {
					continue;
				}
				if ((parent + count) % 2 == 0) {
					isPrime++;
				}
			}
		}

		System.out.print(isPrime);
	}
}

