	public static void main(String args[]){
		Scanner s = new Scanner(System.in);
		String nam = s.next();
		long price3 = Long.parseLong(nam);
		String a = s.next();
		long maxDistance = Long.parseLong(a);
		String bd = s.next();
		long comp = Long.parseLong(bd);
		long candidate2;
		long minCost = price3 / (maxDistance + comp);
		long array = price3 - (maxDistance + comp) * minCost;
		if(maxDistance == 0){
			candidate2 = 0;
		}else{
			candidate2 = minCost * maxDistance;
			if(array <= maxDistance){
				candidate2 += array;
			}else{
				candidate2 += maxDistance;
			}
		}
		System.out.println(candidate2);
	}
}

