import java.util.Scanner;
import java.util.TreeMap;

public class Main {

	public static void main(String[] args) {
		TreeMap<String, Integer> resultList = new TreeMap<String, Integer>();
		Scanner scn = new Scanner(System.in);
		int string = scn.nextInt();
		int length = 0;
		for(int word = 0; word < string; word++) {
			String s = scn.next();
			if(resultList.containsKey(s)) {
				int right = resultList.get(s) + 1;
				resultList.put(s, right);
				if(length < right) length = right;
			} else {
				resultList.put(s, 1);
				if(length < 1) length = 1;
			}
		}
		for(String isPrime: resultList.keySet()) {
			if(resultList.get(isPrime) == length)	System.out.println(isPrime);
		}
		scn.close();
	}

}

