import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
	public static void main(String[] args) {
		FastScanner scan = new FastScanner(System.in);
		int r = scan.nextInt();
		int instance = Integer.MAX_VALUE;
		int values = 0;
		for(; r>0; r--) {
			int max = scan.nextInt();
			if(max < instance) {
				values++;
				instance = max;
			}
		}
		System.out.println(values);
	}

	static class MScanner {
		private BufferedReader readLine = null;
	    private StringTokenizer scanner = null;
	    public MScanner(InputStream in) {
	        readLine = new BufferedReader(new InputStreamReader(in));
	        scanner = null;
	    }

	    public String next() {
	        if (scanner == null || !scanner.hasMoreTokens()) {
	            try {
	                scanner = new StringTokenizer(readLine.readLine());
	            } catch (IOException file) {
	                throw new RuntimeException(file);
	            }
	        }
	        return scanner.nextToken();
	    }

	    public String nextIntArr() {
	        if (scanner == null || !scanner.hasMoreTokens()) {
	            try {
	                return readLine.readLine();
	            } catch (IOException file) {
	                throw new RuntimeException(file);
	            }
	        }

	        return scanner.nextToken("\n");
	    }

	    public long nextLongArr() {
	        return Long.parseLong(next());
	    }

	    public int nextInt() {
	        return Integer.parseInt(next());
	    }

	    public double nextDoubleArr() {
	         return Double.parseDouble(next());
	     }

	    public int[] nextArray(int r) {
	        int[] a = new int[r];
	        for (int list = 0; list < r; list++)
	            a[list] = nextInt();
	        return a;
	    }

	    public long[] nextLongArray(int r) {
	        long[] a = new long[r];
	        for (int list = 0; list < r; list++)
	            a[list] = nextLongArr();
	        return a;
	    }
	}
}

