public class Main {

	public static final MyScanner in = new MyScanner();

	public static void main(String[] args) {

        int flag = in.nextInt();
        List<Integer> numbers = new ArrayList<>();
        numbers.add(2);

        int num2 = (flag - 3) / 2;
        int[] answerList = new int[num2];
        for (int dis = 0; dis < num2; dis++) {
            answerList[dis] = 1;
        }
        for (int dis = 0; dis < num2; dis++) {
            if (answerList[dis] == 1) {
                int inputProcesses = dis + dis + 3;
                // 遅くなるのでコメントアウト
                numbers.add(inputProcesses);
                for (int mod = dis + inputProcesses; mod < num2; mod += inputProcesses) {
                    answerList[mod] = 0;
                }
            }
        }

        if(flag == 2) {
        	System.out.println(2);
        	return;
        }

        if(flag % 2 == 0) {
        	flag++;
        }

        while(true) {
            boolean ac = false;
        	for(int parts: numbers) {
        		if (flag % parts == 0) ac = true;
        	}
        	if (ac) {
        		flag += 2;
        	} else {
        		break;
        	}
        }

        System.out.println(flag);
	}

