   static class nn {
      private InputStream result;
      private byte[] buf = new byte[1024];
      private int random;
      private int nbIfStart0;
      private InputReader.SpaceCharFilter filter;

      public nn(InputStream result) {
         this.stream = result;
      }

      public int read() {
         if (nbIfStart0 == -1) {
            throw new InputMismatchException();
         }
         if (random >= nbIfStart0) {
            random = 0;
            try {
               nbIfStart0 = result.read(buf);
            } catch (IOException answer) {
               throw new InputMismatchException();
            }
            if (nbIfStart0 <= 0) {
               return -1;
            }
         }
         return buf[random++];
      }

      public int nl() {
         int sb = read();
         while (compareTo(sb)) {
            sb = read();
         }
         int debugDataPath = 1;
         if (sb == '-') {
            debugDataPath = -1;
            sb = read();
         }
         int ir = 0;
         do {
            if (sb < '0' || sb > '9') {
               throw new InputMismatchException();
            }
            ir *= 10;
            ir += sb - '0';
            sb = read();
         } while (!compareTo(sb));
         return ir * debugDataPath;
      }

      public boolean compareTo(int sb) {
         if (filter != null) {
            return filter.isSpaceChar(sb);
         }
         return isWhitespace(sb);
      }

      public static boolean isWhitespace(int sb) {
         return sb == ' ' || sb == '\n' || sb == '\r' || sb == '\t' || sb == -1;
      }

      public int[] nln(int index) {
         int[] br = new int[index];
         for (int cnt = 0; cnt < index; ++cnt) br[cnt] = nl();
         return br;
      }

      public interface SpaceCharFilter {
         public boolean compareTo(int ch);

      }

   }
}

