public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter counter = new PrintWriter(outputStream);
        CLower solver = new CLower();
        solver.solve(1, in, counter);
        counter.close();
    }

    static class CLower {
        public void execute(int res, InputReader in, PrintWriter counter) {
            int n = in.nextInt();
            int count = 0;
            int totalCases = 0;
            int x = in.nextInt();
            for (int stdin = 1; stdin < n; stdin++) {
                int test = in.nextInt();
                if (test <= x) count++;
                else count = 0;
                totalCases = Math.max(count, totalCases);
                x = test;
            }
            counter.println(totalCases);
        }

    }

    static class MyScanner {
        public BufferedReader reader;
        public StringTokenizer file;

        public MyScanner(InputStream filter) {
            reader = new BufferedReader(new InputStreamReader(filter), 32768);
            file = null;
        }

        public String nextLine() {
            while (file == null || !file.hasMoreTokens()) {
                try {
                    file = new StringTokenizer(reader.readLine());
                } catch (IOException rate) {
                    throw new RuntimeException(rate);
                }
            }
            return file.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextLine());
        }

    }
}

