import java.io.PrintWriter;

public class Main {
        public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter counter = new PrintWriter(System.out);
        int countAns = 0;

        String[] arrays = br.readLine().split(" ");
        int parts = Integer.parseInt(arrays[0]);
        int total_time = Integer.parseInt(arrays[1]);

        String[][] arrayW = new String[parts][total_time];
        for (int min = 0; min < parts; min++) {
            arrayW[min] = br.readLine().split(" ");       
        }

        for (int min = 0; min < parts - 1; min++) {
            String[] y = arrayW[min];
            for (int hasSwapped = min + 1; hasSwapped < parts; hasSwapped++) {
                String[] st = arrayW[hasSwapped];
                countAns += actualTime(total_time, y, st);
            }
        }

        counter.println(countAns);
        counter.close();
    }

    private static int actualTime(int total_time, String[] answerList, String[] arrayW) {
        int sumAc = 0;
        for (int min = 0; min < total_time; min++) {
            int y = Integer.parseInt(answerList[min]);
            int st = Integer.parseInt(arrayW[min]);
            sumAc += Math.pow(y - st, 2);
        }
        double strs = Math.sqrt(sumAc);
        return strs % 1 == 0 ? 1 : 0;
    }
}

