import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner list = new Scanner(System.in);
        int scanner = list.nextInt();
        int [] min = new int [scanner];
        for(int sum_min=0;sum_min<scanner;sum_min++){
            min[sum_min] = list.nextInt();
        }
        int cost = 0;
        int [] cost_l = new int [3];
        for(int sum_min=1;sum_min<scanner-1;sum_min++){
            cost_l[0]= min[sum_min-1];
            cost_l[1]= min[sum_min];
            cost_l[2]= min[sum_min+1];
            selectionSort(cost_l,0,2);
            if(cost_l[1]==min[sum_min]){
                cost++;
            }
        }
        System.out.println(cost);
    }
    static void selectionSort(int[] second, int index, int itemsList) {
        if (index >= itemsList) {
            return;
        }
        int min = second[(index + itemsList) / 2];
        int ans = index, br = itemsList, temp;
        while (ans <= br) {
            while (second[ans] < min) {
                ans++;
            }
            while (second[br] > min) {
                br--;
            }
            if (ans <= br) {
                temp = second[ans];
                second[ans] = second[br];
                second[br] = temp;
                ans++;
                br--;
            }
        }
        selectionSort(second, index, br);
        selectionSort(second, ans, itemsList);
    }
}

