public class Main {
    public static void main(String[] args) {
        final Scanner in = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        final int counter = in.nextInt();
        final int digit_100 = in.nextInt();

        int value = 0;
        for (int max = 0; max < counter; max++) {
            value += digit_100 + max;
        }
        if (digit_100 >= 0) {
            value -= digit_100;
            System.out.println(value);
        } else {
            if (digit_100 + counter - 1 >= 0) {
                System.out.println(value);
            } else {
                value -= digit_100 + counter - 1;
                System.out.println(value);
            }
        }
    }
}

import java.util.*;

public class Main{
    public static void main(String args[]){
        Scanner mid = new Scanner(System.in);

        long curans = mid.nextLong();
        long b = mid.nextLong();
        long begin = mid.nextLong();
        long cards = mid.nextLong();

        long mod = b - curans + 1;

        mod -= getMin(curans, b, begin);
        mod -= getMin(curans, b, cards);
        mod += getMin(curans, b, divn(begin, cards));

        System.out.println(mod);
        mid.close();
    }

    static long max(long scan, long index) {
        if (scan < index)
            return max(index, scan);
        if(index == 0)
            return scan;
        return max(index, scan%index);
    }

    static long divn(long scan, long index){
        return ((scan*index) / max(scan, index));
    }

    static long getMin(long curans, long b, long index){
        if(curans%index == 0)
            return ((b/index) - (curans/index) + 1);
        else
            return ((b/index) - (curans/index));
    }
}

