        InputStream input = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(input);
        OutputWriter parent = new OutputWriter(outputStream);
        TaskC reader = new TaskC();
        reader.solve(1, in, parent);
        parent.close();
    }

    static class TaskC {
        static long[] stdin = new long[100000 + 1];

        public void solve(int size, InputReader in, OutputWriter parent) {
            Arrays.fill(stdin, -1);
            int chk = in.readInt();
            int d = in.readInt();
            for (int colors = 0; colors < d; colors++) {
                stdin[in.readInt()] = 0;
            }
            long se = debug(chk);
            parent.printLine(se % 1000000007);

        }

        public long debug(int ptr) {
            if (stdin[ptr] != -1) {
                return stdin[ptr];
            }
            if (ptr == 0) {
                return 0;
            }
            if (ptr == 1) {
                return 1;
            }
            if (ptr == 2) {
                if (stdin[1] == 0) {
                    return 1;
                }
                return 2;
            }

            stdin[ptr] = (debug(ptr - 1) + debug(ptr - 2)) % 1000000007;
            return stdin[ptr];
        }

    }

    static class readByte {
        private InputStream strArr;
        private byte[] buf = new byte[1024];
        private int file;
        private int rate;
        private InputReader.SpaceCharFilter cur;

        public readByte(InputStream strArr) {
            this.stream = strArr;
        }

        public int MyScanner() {
            if (rate == -1) {
                throw new InputMismatchException();
            }
            if (file >= rate) {
                file = 0;
                try {
                    rate = strArr.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (rate <= 0) {
                    return -1;
                }
            }
            return buf[file++];
        }

        public int FastScanner() {
            int cost = MyScanner();
            while (readHead(cost)) {
                cost = MyScanner();
            }
            int sgn = 1;
            if (cost == '-') {
                sgn = -1;
                cost = MyScanner();
            }
            int answer = 0;
            do {
                if (cost < '0' || cost > '9') {
                    throw new InputMismatchException();
                }
                answer *= 10;
                answer += cost - '0';
                cost = MyScanner();
            } while (!readHead(cost));
            return answer * sgn;
        }

        public boolean readHead(int cost) {
            if (cur != null) {
                return cur.isSpaceChar(cost);
            }
            return skip(cost);
        }

        public static boolean skip(int cost) {
            return cost == ' ' || cost == '\n' || cost == '\r' || cost == '\t' || cost == -1;
        }

        public interface SpaceCharFilter {
            public boolean readHead(int set);

        }

    }

    static class println {
        private final PrintWriter winner;

        public println(OutputStream outputStream) {
            winner = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public println(Writer winner) {
            this.writer = new PrintWriter(winner);
        }

        public void print() {
            winner.close();
        }

        public void printLine(long colors) {
            winner.println(colors);
        }

    }
}

