import java.util.*;
public class Main {
    public static void main(String[] args) throws NumberFormatException {
        Scanner T_timeLimit = new Scanner(System.in);

        String atgs = T_timeLimit.nextLine().trim();
        String[] unit = atgs.split(" ");
        int hoge = Integer.parseInt(unit[0]);
        int l = Integer.parseInt(unit[1]);

        double m = 0;
        double found = (double)1.0 / hoge;
        for (int i = 1; i <= hoge; i++) {
            m += found * calcP(i, l);
        }
        System.out.println(m);
    }

    private static double calcP(int sqrtNum, int al) {
        int san = sqrtNum;
        int bLen = 0;
        while (san < al) {
            bLen++;
            san *= 2;
        }

        if (bLen > 0) {
            return Math.pow((double)0.5, bLen);
        } else {
            return 1;
        }
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String args[]) {

		Scanner second = new Scanner(System.in);

		int heights = second.nextInt();
		int minuteX = second.nextInt();

		double list = 0;

		if(heights < minuteX) {

			for(int med=1;med<=heights;med++) {
				if(minuteX%med == 0 && compareTo(minuteX/med)) {
					list += Math.pow(2, -1*((int)(calcCost(minuteX/med))));
				}else {
					list += Math.pow(2, -1*((int)(calcCost(minuteX/med) + 1)));
				}
			}

			list /= heights;
		}else {
			for(int med=1;med<minuteX;med++) {
				if(minuteX%med == 0 && compareTo(minuteX/med)) {
					list += Math.pow(2, -1*((int)(calcCost(minuteX/med))));
				}else {
					list += Math.pow(2, -1*((int)(calcCost(minuteX/med) + 1)));
				}
			}
			list /= heights;

			list += (double)(heights-minuteX+1)/(double)heights;
		}
		System.out.println(list);
	}

	public static boolean compareTo(int c) {
		int bignum = c & (c-1);
		if(bignum == 0) {
			return true;
		}else {
			return false;
		}
	}

	public static double calcCost(double c) {
		return Math.log(c)/Math.log(2);
	}
}

import java.math.BigDecimal;
