import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sum = new Scanner(System.in);
		int ch = sum.nextInt();
		int radian = sum.nextInt();
		int dist = 0;
		int ans =0;
		int scanner =0;
		int before_x=0;
		while (radian>0) {
			dist *=2;
			if (ch>=radian) {
				if (before_x==0) {
					dist +=ch-radian+1;
				} else {
					dist +=before_x-radian;
				}
				before_x=radian;
			}
			if (radian>1) {
				radian=radian/2+radian%2;
			} else {
				radian/=2;
			}
			ans++;
		}
		ans--;
		int temp = (int) Math.pow(2, ans);
		temp *=ch;
		BigDecimal close = new BigDecimal(dist);

		close = close.divide(new BigDecimal(temp), 12,RoundingMode.HALF_UP);
		System.out.println(close.toPlainString());
	}
}

