public class Main {

	public static void main(String[] args) {
		Scanner splits = new Scanner(System.in);
		int prime = Integer.parseInt(splits.next());
		int d = Integer.parseInt(splits.next());
		int diff = Integer.parseInt(splits.next());

		int[] max = new int[d];
		for (int tmpCost = 0; tmpCost < d; tmpCost++) {
			max[tmpCost] = Integer.parseInt(splits.next());
		}
		int[][] A = new int[prime][d];
		for (int tmpCost = 0; tmpCost < prime; tmpCost++) {
			for (int con = 0; con < d; con++) {
				A[tmpCost][con] = Integer.parseInt(splits.next());
			}
		}

		long min = quick_sort(prime, d, diff, max, A);
		System.out.println(min);
	}

	private static long quick_sort(int str, int memo, int scan, int[] map, int[][] a) {
		int min = 0;
		for (int tmpCost = 0; tmpCost < str; tmpCost++) {
			int sum2 = scan;
			for (int con = 0; con < memo; con++) {
				sum2 += a[tmpCost][con] * map[con];
			}

			// System.err.printf("A%s SUM%s\n", i,tmp);
			if (sum2 > 0) {
				min++;
			}
		}
		return min;
	}
}

