public class Main {
	Scanner ans = new Scanner(System.in);

	static int answerList;
	void bubblesort() {
		int ret = ans.nextInt();
		int[] isNotPrime = new int[ret];
		int count = 101;
		answerList = 0;
		for(int anss = 0; anss < ret; anss++) {
			isNotPrime[anss] = ans.nextInt();
			if(isNotPrime[anss] < count)count = isNotPrime[anss];
		}
		printPossibleBlack(isNotPrime, 0, ret - 1, 0);
		System.out.println(answerList);
	}

	void printPossibleBlack(int[] isNotPrime, int data, int exIndex1, int changed) {
		if(data > exIndex1)return;
		int count = 101, inputs = -1;
		for(int anss = data; anss <= exIndex1; anss++) {
			if(count > isNotPrime[anss]) {
				count = isNotPrime[anss];
				inputs = anss;
			}
		}
		answerList += count - changed;
		if(count <= changed)count = changed;
		if(count - changed == 0) changed = 0;
		printPossibleBlack(isNotPrime, data, inputs - 1, count);
		printPossibleBlack(isNotPrime, inputs + 1, exIndex1, count);
	}
	public static void main(String[] args) {
		new Main().doIt();
	}
}

