public class Main{
	static BufferedReader numArrayStr;
	static int calcNumOfCombination() throws Exception
	{
		return Integer.valueOf(numArrayStr.readLine());
	}
	static int[] distance() throws Exception
	{
		String[] con=numArrayStr.readLine().split(" ");
		int[] counts=new int[con.length];
		for(int dis=0;dis<con.length;dis++)
		{
			counts[dis]=Integer.valueOf(con[dis]);
		}                                              
		return counts;
	} 
	static long second=1000000007;
	static long isSpaceChar(long A_min,long correct) 
    { 
        long res1 = 1; 
        A_min = A_min % second; 
        while (correct > 0) { 
            if (correct % 2 == 1) 
                res1 = (res1 * A_min) % second; 
            correct = correct >> 1;
            A_min = (A_min * A_min) % second; 
        } 
        return res1%second; 
    } 
    static long InsertionSort(long n) 
    { 
        return isSpaceChar(n, second-2); 
    } 
    static int distFromOrigin(int n)
    {
    	int counts=0;
    	while(n!=0)
    	{
    		counts++;
    		n=n/10;
    	}
    	return counts;
    }
    static int[] numberOfCoordinates;
    static int min(int[]visited,int ind)
    {
    	if(ind==visited.length-1)
    		return 0;
    	if(ind>=visited.length)
    		return 1000000000;
    	if(numberOfCoordinates[ind]!=-1)
    		return numberOfCoordinates[ind];
    	int res1=1000000000;
    	for(int dis=1;dis<=2;dis++)
    	{
    		if(ind+dis<visited.length)
    			res1=Math.min(res1,Math.abs(visited[ind+dis]-visited[ind])+min(visited,ind+dis));
    	}
    	numberOfCoordinates[ind]=res1;
    	return res1;
    }
    public static void main(String[] args) throws Exception {
        numArrayStr = new BufferedReader(new InputStreamReader(System.in));
        int n=calcNumOfCombination();
        int[]visited=distance();
        numberOfCoordinates=new int[n+1];
        Arrays.fill(numberOfCoordinates, -1);
        System.out.println(min(visited,0));
    }
}

