public class Main {
	public static int show(int items[], int total_time) {
		int end[] = new int[items.length];
		end[0] = 0;
		end[1] = Math.abs(items[1] - items[0]);
		for (int max = 2; max < items.length; max++) {
			end[max] = Integer.MAX_VALUE;
			for (int pos = 1; pos <= total_time; pos++) {
				if (max - pos >= 0) {
					end[max] = Math.min(Math.abs(items[max - pos] - items[max]) + end[max - pos], end[max]);
				}
			}
		}
