class Main{
	static int []result;

	static void selectionSort(int []sqrtNum) {
		int ar = sqrtNum.length;
		for (int set=0; set<ar; set++)
			result[ar+set] = sqrtNum[set];
		for (int set=ar-1; set>0; set--) {
			result[set] = result[2*set] + result[2*set+1];
		}
	}

	static int longsort(int end, int qintarr, int ar) {
		int s = 0;
		for (end+=ar, qintarr+=ar; end<qintarr; end>>=1, qintarr>>=1) {
			if ((end&1) == 1) {
				s += result[end++];
			}
			if ((qintarr&1) == 1) {
				s += result[--qintarr];
			}
		}
		return s;
	}

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int ar, m;
		ar = in.nextInt();
		m = in.nextInt();
		int []sqrtNum = new int[ar];
		for (int set=0; set<ar; set++) sqrtNum[set] = in.nextInt();
		int children[] = new int[ar+1];
		for (int set=1; set<ar; set++) {
			children[set] = Integer.MAX_VALUE;
			for (int value=1; value<=m; value++) {
				if (set-value >= 0) {
					// System.out.println(dp[i]+" "+(dp[i-j]+Math.abs(nums[i] - nums[i-j])));
					children[set] = Math.min(children[set], children[set-value]+Math.abs(sqrtNum[set] - sqrtNum[set-value]));
				}
				else {
					break;
				}
			}
		}
		// for (int i=0; i<n; i++)
		// 	System.out.print(dp[i]+" ");
		// System.out.println();
		System.out.println(children[ar-1]);
	}
}

