public class Main {

    public static void hashCode(InputReader in, PrintWriter numberOfPeople) throws Exception {

        int read = in.nextInt();
        int m = in.nextInt();


        int[] tmpLine = new int[read+1];

        for(int toi=1;toi<=read;toi++)
            tmpLine[toi]=in.nextInt();

        int[] toori = new int[read+1];

        toori[0]=0;
        toori[1]=0;
        toori[2]= Math.abs(tmpLine[2]-tmpLine[1]);


        for(int toi=3;toi<=read;toi++)
        {
            int cumulate=toi;
            int candyList=1;
            toori[toi]=Integer.MAX_VALUE;
            while(cumulate-candyList>=1 && candyList<=m)
            {
                toori[toi]= Math.min(toori[toi],Math.abs(tmpLine[toi]-tmpLine[cumulate-candyList])+toori[cumulate-candyList]);
                candyList++;
            }

        }
        numberOfPeople.println(toori[read]);

    }

    /////////////////////////////////////////////////////////


    private final static long bubbleSort(long ch, long answer) {
        ch += first;
        answer += first;
        return ch << 32 | answer;
    }

    private final static int first = (int) 3e5;

    public static void main(String[] args) throws Exception {
        InputStream strArr = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(strArr);
        PrintWriter numberOfPeople = new PrintWriter(outputStream);
        hashCode(in, numberOfPeople);
        numberOfPeople.close();
    }

    static class readBody {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public readBody(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        private String nextToken() throws IOException {
            while (tokenizer == null || !tokenizer.hasMoreTokens())
                tokenizer = new StringTokenizer(reader.readLine());
            return tokenizer.nextToken();
        }

        public String nextLine() throws IOException {
            return reader.readLine();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        public long nextChar() throws IOException {
            return Long.parseLong(nextToken());
        }

        public double nextIntArray1Index() throws IOException {
            return Double.parseDouble(nextToken());
        }

    }
}

