public class Main {
  public static void main(String[] args) {


    Scanner s2 = new Scanner(System.in);
    // get a integer

    int data = s2.nextInt();
//    System.out.println(" integer is " + N);
    List<Integer> continueFlag = new ArrayList<>();
    List<Integer> tail_point = new ArrayList<>();
    int current1 = s2.nextInt();
    int coordinateList = -1, check = -1, ansz = -1;
//    Y = 10000 * x + 5000 * y + 1000 *z;
//    N = x + y + z;
//    z = N - x - y;
//    z = (Y - (10000 * x + 5000 * y)) /1000;


    for(int ans_num = 0; ans_num <= data ; ans_num++){
      // i is equal to x
      double value = getX(ans_num, data,  current1);
      double caluculatedZ = data -ans_num - value;
      if(Coordinate(value,caluculatedZ, data)){
        coordinateList = ans_num;
        check = (int)value;
        ansz = (int)caluculatedZ;
        break;
      }
    }
    System.out.println(coordinateList + " " + check + " " + ansz);

  };
  private static double getX(int ans_num,int data, int current1) {
//    Y = 10000 * x + 5000 * y + 1000 * (N - x - y);
//    Y = 10000 * x + 5000 * y + 1000 *N - 1000* x - 1000* y;
//    Y = 9000*x + 4000*y + 1000*N
//
    double children = ((double)current1 - 9000 * (double)ans_num  - 1000* (double)data ) /4000;
    return children;
  }

  public static boolean factorialUsingRecursion(double a1, double data) {
    if(a1 ==(int)a1 && a1 >= 0 && a1 <= data){
      return true;
    }else{
      return false;
    }
  }
  public static boolean Coordinate(double children, double dist, int data) {
    boolean yflag = false, taro = false;
    if(factorialUsingRecursion(children, data)){
      yflag = true;
    };
    if(factorialUsingRecursion(dist, data)){
      taro = true;
    }
    return yflag && taro;
  }
}

