public class Main {

    public static void main(String[] args) {

        Scanner total = new Scanner(System.in);
        int len = total.nextInt();
        int cost = total.nextInt();
        int d = total.nextInt();
        List<Integer> result = new ArrayList<Integer>();
        for(int sqrt=0; sqrt<= len; sqrt++) {
            int sum = gettotal(sqrt);

            if (cost <= sum && d >= sum) {
                result.add(sqrt);
            }
        }

        int ss = 0;
        for (int sqrt=0; sqrt < result.size(); sqrt++) {
            ss = ss + result.get(sqrt);
        }
        System.out.print(ss);
    }

    private static int gettotal(int sqrt) {
        int sum = 0;
        while(sqrt !=0) {
            sum += sqrt % 10;
            sqrt /= 10;
        }
        return sum;
    }
}

