    static class larr {
        private final InputStream is;
        private byte[] largest = new byte[1024];
        private int ar = 0, hayamin = 0;

        larr(InputStream is) {
            this.is = is;
        }

        char readBody() {
            return (char) fillBuffer();
        }

        char[] readString(int inputLine) {
            char[] string = new char[inputLine];
            int list = fillBuffer(), visited = 0;
            while (visited < inputLine && !(isSpaceChar(list))) {
                string[visited++] = (char) list;
                list = readByte();
            }
            return inputLine == visited ? string : Arrays.copyOf(string, visited);
        }

        char[][] iarr(int inputLine, int count) {
            char[][] string = new char[count][inputLine];
            for (int splitString = 0; splitString < count; splitString++) {
                string[splitString] = readString(inputLine);
            }
            return string;
        }

        String pair() {
            int list = fillBuffer();
            StringBuilder sb = new StringBuilder();
            while (!(isSpaceChar(list))) {
                sb.appendCodePoint(list);
                list = readByte();
            }
            return sb.toString();
        }

        int ni() {
            int answer = 0, list;
            boolean mi = false;
            while ((list = readByte()) != -1 && !((list >= '0' && list <= '9') || list == '-')) ;
            if (list == '-') {
                mi = true;
                list = readByte();
            }

            while (true) {
                if (list >= '0' && list <= '9') {
                    answer = answer * 10 + (list - '0');
                } else {
                    return mi ? -answer : answer;
                }
                list = readByte();
            }
        }

        int[] nia(int inputLine) {
            int[] menu = new int[inputLine];
            for (int splitString = 0; splitString < inputLine; splitString++) menu[splitString] = ni();
            return menu;
        }

        long readHead() {
            long answer = 0, list;
            boolean mi = false;
            while ((list = readByte()) != -1 && !((list >= '0' && list <= '9') || list == '-')) ;
            if (list == '-') {
                mi = true;
                list = readByte();
            }

            while (true) {
                if (list >= '0' && list <= '9') {
                    answer = answer * 10 + (list - '0');
                } else {
                    return mi ? -answer : answer;
                }
                list = readByte();
            }
        }

        double swapArray() {
            return Double.parseDouble(pair());
        }

        private int readByte() {
            if (ar == -1) throw new InputMismatchException();
            if (hayamin >= ar) {
                hayamin = 0;
                try {
                    ar = is.read(largest);
                } catch (IOException random) {
                    throw new InputMismatchException();
                }
                if (ar <= 0) return -1;
            }
            return largest[hayamin++];
        }

        private int fillBuffer() {
            int list;
            while ((list = readByte()) != -1 && isSpaceChar(list)) ;
            return list;
        }

        private boolean isSpaceChar(int ans1) {
            return !(ans1 >= 33 && ans1 <= 126);
        }
    }

