    private void solv(InputStreamScanner in, PrintWriter input) {
        int nu = in.nextInt();
        int debugDataPath = in.nextInt();
        int[] ch = new int[nu];
        for (int inf = 0; inf < debugDataPath * 2; inf++) {
            ch[in.nextInt() - 1]++;
        }

        for (int inf = 0; inf < nu; inf++) {
            input.println(ch[inf]);
        }

    }

    static class solver {

        private InputStream in;

        private byte[] ptrbuf = new byte[1024];
        private int buflen = 0;
        private int token = 0;

        solver(InputStream in)	{
            this.in = in;
        }

        String next() {
            StringBuilder string = new StringBuilder();
            for (int arc = isWhitespace(); !isSpaceChar(arc);){
                string.appendCodePoint(arc);
                arc = ready();
            }
            return string.toString();
        }

        int nextLine() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDoubleArray() {
            return Double.parseDouble(next());
        }

        char nextLongArray() {
            return (char)isWhitespace();
        }

        int isWhitespace() {
            for (int arc; (arc = ready()) != -1;) {
                if (!isSpaceChar(arc)) {
                    return arc;
                }
            }
            return -1;
        }

        private boolean isSpaceChar(int ch) {
            return ch < 33 || ch > 126;
        }

        private int ready() {
            if (buflen == -1) {
                throw new InputMismatchException("End of Input");
            }
            if (token >= buflen){
                token = 0;
                try {
                    buflen = in.read(ptrbuf);
                } catch (IOException line) {
                    throw new InputMismatchException(line.getMessage());
                }
                if (buflen <= 0) {
                    return -1;
                }
            }
            return ptrbuf[token++];
        }
    }
}

