import java.util.Scanner;

public class Main {

	public static void main(String[] args) {


		Scanner ic = new Scanner(System.in);
		int divisorCount = ic.nextInt();
		int counter = ic.nextInt();
		int prev = 0;
		for(int countEightDivisor = 0;countEightDivisor <= divisorCount;countEightDivisor++) {
			if(countEightDivisor > counter) {
				break;
			}
			for(int remain = 0;remain <= divisorCount;remain++) {
				if(countEightDivisor + remain > counter) {
					break;
				}else {
					if(countEightDivisor + remain + divisorCount >= counter) {
						prev++;
					}
				}
			}
		}
		System.out.println(prev);
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws Exception {
        Scanner sb = new Scanner(System.in);

        int resultCount = sb.nextInt();
        int maxL = sb.nextInt();

        int towns = 0;
        for (int total = 0; total <= resultCount; total++) {
        	for (int price = 0; price <= resultCount; price++) {
        		if (total+price > maxL)
        			break;

        		if (maxL - (total + price) <= resultCount) {
        			towns++;
        		}
        	}
        }

        System.out.println(towns);
    }
}
